template.script:
(function () {
    var el = document.getElementById("ac-tab-favicon");
    var href = el ? el.getAttribute("href") : "";
    if (!href) { return; }
    var nodes = document.querySelectorAll("link[rel*='icon']");
    var i;
    for (i = 0; i < nodes.length; i++) {
        nodes[i].setAttribute("href", href);
    }
})();
